<script lang="ts">
  import MetricCard from '$lib/components/MetricCard.svelte';
  import PerformanceChart from '$lib/components/PerformanceChart.svelte';
  import { recommendAd } from '$lib/growth/rules';
  export let data:{live:boolean;error:string|null;period:{range:string;label:string};shopCurrency:string;metaCurrencies:string[];displayCurrency:string;fxApprox:boolean;fxRates:Record<string,number>;overview:{revenue:number;spend:number;roas:number;orders:number;conversionRate:number;cpa:number;sessions:number;addToCart:number;checkout:number;avgSessionActiveMs:number};behavior:{topTimePath:string;topTimeAvgMs:number;topTimeSessions:number;topExitPath:string;topExitCount:number;topExitShare:number};trend:{label:string;revenue:number;spend:number}[];ads:{name:string;spend:number;revenue:number;purchases:number;ctr:number;cpc:number;cpm:number;atcRate:number;currency:string}[]};
  const money=(n:number,currency='RSD')=>{try{return new Intl.NumberFormat('sr-RS',{style:'currency',currency,maximumFractionDigits:currency==='RSD'?0:2}).format(n)}catch{return`${new Intl.NumberFormat('sr-RS',{maximumFractionDigits:2}).format(n)} ${currency}`}};
  const pct=(n:number)=>`${n.toFixed(1)}%`,rate=(a:number,b:number)=>b?a/b*100:0,dur=(ms:number)=>{const s=Math.max(0,Math.round(ms/1000));return s<60?`${s}s`:`${Math.floor(s/60)}m ${s%60}s`;};
  const status=(s:string)=>({SCALE:'SKALIRAJ',KEEP:'OSTAVI',WATCH:'PRATI',PAUSE:'PAUZIRAJ',WEBSITE_ISSUE:'PROBLEM SAJT',LOW_SAMPLE:'MALO PODATAKA'}[s]||s);const href=(r:string)=>`/?range=${r}`;
  $: atcRate=rate(data.overview.addToCart,data.overview.sessions);$: checkoutRate=rate(data.overview.checkout,data.overview.addToCart);$: funnelMessage=!data.overview.sessions?'Nema sesija u izabranom periodu.':atcRate<4?`Najveći pad je poseta → korpa: ${pct(atcRate)} sesija je dodalo proizvod.`:data.overview.addToCart>0&&checkoutRate<35?`Najveći pad je korpa → checkout: prolazi ${pct(checkoutRate)} ATC sesija.`:'Funnel nema očigledan kritičan pad u prvim koracima.';
</script>
<header><div><div class="eyebrow">TRENDYPATIKE · GROWTH CONTROL</div><h1>Pregled poslovanja</h1><p>Prodaja, oglasi i ponašanje kupaca u jednom prikazu. Izaberi period i odmah vidi gde curi prihod.</p></div><div class="live"><i></i>{data.live?'podaci uživo':'čekam podatke'}</div></header>
<nav class="periods" aria-label="Period analitike"><a class:active={data.period.range==='today'} href={href('today')}>Danas</a><a class:active={data.period.range==='yesterday'} href={href('yesterday')}>Juče</a><a class:active={data.period.range==='7d'} href={href('7d')}>7 dana</a><a class:active={data.period.range==='30d'} href={href('30d')}>30 dana</a></nav>
{#if data.error}<div class="error"><b>Dijagnostika:</b> {data.error}</div>{/if}
<section class="metrics"><MetricCard label={`Prihod · ${data.period.label}`} value={money(data.overview.revenue,data.shopCurrency)} note="Shopify · važeće porudžbine" explain="Prihod od Shopify porudžbina u izabranom periodu koje nisu otkazane/refundirane." formula="zbir validnih order total vrednosti" interpretation="Prodaja, ne profit."/><MetricCard label={`Porudžbine · ${data.period.label}`} value={String(data.overview.orders)} note={`${data.overview.conversionRate.toFixed(2)}% sesija → order`} explain="Broj validnih Shopify porudžbina u periodu." formula="broj validnih orders" interpretation="Stopu gledaj zajedno sa kvalitetom saobraćaja."/><MetricCard label={`Sesije · ${data.period.label}`} value={data.overview.sessions.toLocaleString('sr-RS')} note={`${data.overview.addToCart} korpa · ${data.overview.checkout} checkout`} explain="Jedna tracker sesija traje dok kupac ne bude neaktivan oko 30 minuta." formula="jedinstveni storefront session ID-jevi" interpretation="Najbitnije je koliko sesija prelazi u korpu i checkout."/><MetricCard label="Aktivno vreme" value={dur(data.overview.avgSessionActiveMs)} note="prosek po sesiji" explain="Vreme aktivnog korišćenja sajta." formula="aktivno vreme ÷ sesije" interpretation="Kratko vreme + visok izlaz obično znači slab interes ili trenje rano na stranici."/><MetricCard label={`Meta ROAS · ${data.period.label}`} value={data.overview.roas.toFixed(2)} note={`normalizovano u ${data.displayCurrency}`} explain="Meta pripisan prihod podeljen Meta troškom nakon konverzije valuta." formula="Meta purchase value ÷ Meta spend" interpretation="Valute se prvo svode na jednu valutu."/><MetricCard label={`Meta CPA · ${data.period.label}`} value={data.overview.cpa?money(data.overview.cpa,data.displayCurrency):'—'} note={`normalizovano u ${data.displayCurrency}`} explain="Trošak Meta oglasa po pripisanoj kupovini nakon FX konverzije." formula="Meta spend ÷ Meta purchases" interpretation="Niži CPA je bolji samo uz dovoljan kvalitet kupovine."/></section>
<section class="plain-grid"><article><span>GDE NAJVIŠE OSTAJU</span><b>{data.behavior.topTimePath||'—'}</b><p>{data.behavior.topTimePath?`Oko ${dur(data.behavior.topTimeAvgMs)} aktivno po poseti · ${data.behavior.topTimeSessions} sesija.`:'Još nema dovoljno podataka.'}</p><a href={`/heatmaps?range=${data.period.range}`}>Otvori ponašanje →</a></article><article><span>GDE NAJČEŠĆE ZAVRŠE</span><b>{data.behavior.topExitPath||'—'}</b><p>{data.behavior.topExitPath?`${data.behavior.topExitCount} sesija · ${pct(data.behavior.topExitShare)} poslednjih stranica.`:'Još nema dovoljno podataka.'}</p><a href="/sessions">Vidi sesije →</a></article><article><span>GLAVNI FUNNEL SIGNAL</span><b>{funnelMessage}</b><p>Sesije → korpa {pct(atcRate)} · korpa → checkout {data.overview.addToCart?pct(checkoutRate):'—'}.</p><a href="/funnel">Otvori funnel →</a></article></section>
<section class="panel chart-panel"><div class="panel-head"><div><div class="eyebrow">{data.period.label.toUpperCase()}</div><h2>Prodaja i Meta trošak u istoj valuti</h2></div></div><PerformanceChart rows={data.trend}/><div class:warn={data.fxApprox} class="currency-note">Shopify i Meta grafikon su prikazani u <b>{data.displayCurrency}</b>. {#if data.metaCurrencies.length}Meta izvori: {data.metaCurrencies.join(', ')}. {#each Object.entries(data.fxRates) as [c,r]}{#if c!==data.displayCurrency}<span>1 {c} ≈ {r.toFixed(2)} {data.displayCurrency}</span>{/if}{/each}{/if}{#if data.fxApprox}<strong> Privremeno je korišćen fallback kurs jer live FX servis nije odgovorio.</strong>{/if}</div></section>
<div class="cols"><section class="panel"><div class="panel-head"><div><div class="eyebrow">OGLASI · {data.period.label.toUpperCase()}</div><h2>Brza procena</h2></div><a href="/ads">Svi detalji →</a></div>{#if data.ads.length}<div class="list">{#each data.ads.slice(0,6) as ad}{@const rec=recommendAd(ad)}<article><div><strong>{ad.name}</strong><small>Spend {money(ad.spend,ad.currency||'RSD')} · CPM {money(ad.cpm,ad.currency||'RSD')} · CTR {ad.ctr.toFixed(2)}% · {ad.purchases} kup.</small></div><span class:good={rec.status==='SCALE'||rec.status==='KEEP'} class:bad={rec.status==='PAUSE'} class:warn={rec.status==='WATCH'||rec.status==='WEBSITE_ISSUE'||rec.status==='LOW_SAMPLE'}>{status(rec.status)}</span><p>{rec.reason}</p></article>{/each}</div>{:else}<div class="empty">Nema Meta podataka za izabrani period.</div>{/if}</section><section class="panel"><div class="panel-head"><div><div class="eyebrow">FUNNEL · {data.period.label.toUpperCase()}</div><h2>Put do kupovine</h2></div><a href="/funnel">Detaljno →</a></div><div class="funnel"><div><b>{data.overview.sessions}</b><span>sesije</span></div><em>↓</em><div><b>{data.overview.addToCart}</b><span>korpa</span></div><em>↓</em><div><b>{data.overview.checkout}</b><span>checkout</span></div><em>↓</em><div><b>{data.overview.orders}</b><span>porudžbine</span></div></div></section></div>
